args.content:
{
  "title": "Task一覧表",
  "icon": "checklist",
  "dataPath": "data/task-list/items",
  "primaryKey": "id",
  "fields": {
    "id": { "type": "string", "label": "ID", "primary": true, "required": true },
    "title": { "type": "string", "label": "Task名", "required": true },
    "summary": { "type": "text", "label": "要約" },
    "category": {
      "type": "enum",
      "label": "カテゴリ",
      "values": ["submittal", "RFI", "drawing", "vendor", "report", "other"],
      "required": true
    },
    "assignee": { "type": "string", "label": "担当者" },
    "due_date": { "type": "date", "label": "期限" },
    "priority": {
      "type": "enum",
      "label": "優先度",
      "values": ["high", "mid", "low"],
      "required": true
    },
    "status": {
      "type": "enum",
      "label": "ステータス",
      "values": ["open", "in progress", "done"],
      "required": true
    },
    "done": {
      "type": "toggle",
      "label": "完了",
      "field": "status",
      "onValue": "done",
      "offValue": "open"
    },
    "approval": {
      "type": "enum",
      "label": "承認",
      "values": ["candidate", "approved", "rejected"],
      "required": true
    },
    "source": { "type": "string", "label": "出典" },
    "received_date": { "type": "date", "label": "受信日" }
  },
  "displayField": "title",
  "kanbanField": "status",
  "calendarField": "due_date",
  "views": [
    {
      "id": "board",
      "label": "Task管理",
      "icon": "table_view",
      "file": "views/board.html",
      "capabilities": ["read", "write"]
    }
  ]
}
